sys_script_client.script:
function onLoad() {

    var gaDetails = new GlideAjax('EventUtilsClient');
    gaDetails.addParam('sysparm_name', 'getEventDetails');
    gaDetails.addParam('sysparm_eventId', g_form.getUniqueValue());
    gaDetails.getXMLAnswer(function(response) {
        var eventDetails = JSON.parse(response);
        g_form.addInfoMessage(eventDetails.event_name + " " + eventDetails.location);
    });

    var gaVIP = new GlideAjax('EventUtilsClient');
    gaVIP.addParam('sysparm_name', 'isVIPEvent');
    gaVIP.addParam('sysparm_eventId', g_form.getUniqueValue());
    gaVIP.getXMLAnswer(function(response) {
        if (response === 'true') {
            alert("This is a VIP Event!");
        }
    });
}
